// Checks the C++ engine against progressions generated by the original FL Studio script.
// Usage: EngineParityTest <path to reference_cases.txt>

#include "../source/engine/ChordEngine.h"

#include <fstream>
#include <iostream>
#include <sstream>

int main (int argc, char** argv)
{
    const std::string path = argc > 1 ? argv[1] : "tests/reference_cases.txt";
    std::ifstream in (path);
    if (! in)
    {
        std::cerr << "Cannot open " << path << "\n";
        return 2;
    }

    int total = 0, failed = 0;
    std::string line;
    while (std::getline (in, line))
    {
        if (line.empty() || line[0] == '#')
            continue;
        const auto bar = line.find (" | ");
        std::istringstream head (line.substr (0, bar));
        sauce::Settings s;
        int bassOn = 1;
        head >> s.key >> s.style >> s.mood >> s.seed >> s.bars >> s.length >> s.voicing >> s.richness >> s.spice >> s.octave >> bassOn;
        s.bassOn = bassOn != 0;

        std::ostringstream got;
        bool firstChord = true;
        for (const auto& c : sauce::generate (s))
        {
            if (! firstChord)
                got << ';';
            firstChord = false;
            got << c.name << ' ' << c.bassNote;
            for (int n : c.upper)
                got << ' ' << n;
        }

        const std::string expected = line.substr (bar + 3);
        ++total;
        if (got.str() != expected)
        {
            if (++failed <= 3)
                std::cerr << "MISMATCH: " << line.substr (0, bar) << "\n  expected " << expected << "\n  got      " << got.str() << "\n";
        }
    }

    std::cout << "Engine parity: " << (total - failed) << " / " << total << " match the FL script\n";
    return failed == 0 && total > 0 ? 0 : 1;
}
